body.script:
//
function medFillApplicant(val) {
    var wrap = document.getElementById('med-manual-wrap');
    wrap.style.display = val === '__manual__' ? 'block' : 'none';
}
function checkVisa(v) {
    var full = document.getElementById('service-options-full');
    var green = document.getElementById('service-options-green');
    if(v === 'green') {
        full.style.display = 'none';
        green.style.display = 'block';
    } else {
        full.style.display = 'block';
        green.style.display = 'none';
    }
    document.getElementById('vip-note').style.display = 'none';
}
function checkService(v) {
    document.getElementById('vip-note').style.display = v === 'vip' ? 'block' : 'none';
}
function updateMedFlag(sel) {
    var opt = sel.options[sel.selectedIndex];
    document.getElementById('med-flag').innerHTML = opt.getAttribute('data-flag') || '&#127462;&#127466;';
}

function medValidateStep1() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }

  // Applicant name
  var apSel = document.getElementById('med_applicant_sel');
  var manName = document.getElementById('med_manual_name');
  if (apSel && apSel.value === '__manual__') {
    var mv = manName ? manName.value.trim() : '';
    if (mv.length < 3 || mv.length > 50) { showErr('ap_name_err','Applicant name must be 3-50 characters.'); valid=false; } else hideErr('ap_name_err');
  } else {
    if (!apSel || !apSel.value) { showErr('ap_name_err','Please select or enter applicant name.'); valid=false; } else hideErr('ap_name_err');
  }

  // Visa type
  var vt = document.querySelector('input[name="visa_type"]:checked');
  if (!vt) { showErr('visa_type_err','Please select a visa application type.'); valid=false; } else hideErr('visa_type_err');

  // First name
  var fn = document.querySelector('[name="first_name"]');
  var fnv = fn ? fn.value.trim() : '';
  if (fnv.length < 3 || fnv.length > 50) { showErr('fname_err','First name must be 3-50 characters.'); valid=false; } else hideErr('fname_err');

  // Last name
  var ln = document.querySelector('[name="last_name"]');
  var lnv = ln ? ln.value.trim() : '';
  if (lnv.length < 3 || lnv.length > 50) { showErr('lname_err','Last name must be 3-50 characters.'); valid=false; } else hideErr('lname_err');

  // Mother name
  var mn = document.querySelector('[name="mother_name"]');
  var mnv = mn ? mn.value.trim() : '';
  if (mnv.length < 3 || mnv.length > 50) { showErr('mname_err','Mother\'s name must be 3-50 characters.'); valid=false; } else hideErr('mname_err');

  // Email
  var em = document.querySelector('[name="email"]');
  var emv = em ? em.value.trim() : '';
  if (!emv || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emv)) { showErr('email_err','Please enter a valid email address.'); valid=false; } else hideErr('email_err');

  // Mobile
  var mob = document.querySelector('[name="mobile"]');
  var mobv = mob ? mob.value.trim().replace(/\D/g,'') : '';
  if (mobv.length < 10 || mobv.length > 15) { showErr('mobile_err','Mobile number must be 10-15 digits.'); valid=false; } else hideErr('mobile_err');

  // DOB
  var dob = document.querySelector('[name="dob"]');
  if (!dob || !dob.value) { showErr('dob_err','Please select date of birth.'); valid=false; } else hideErr('dob_err');

  // Marital status
  var ms = document.querySelector('[name="marital_status"]');
  if (!ms || !ms.value) { showErr('marital_err','Please select marital status.'); valid=false; } else hideErr('marital_err');

  // Religion
  var rel = document.querySelector('[name="religion"]');
  if (!rel || !rel.value) { showErr('religion_err','Please select religion.'); valid=false; } else hideErr('religion_err');

  // Document uploads
  var docs = [
    ['doc_passport','doc_pass_err','Passport copy is required.'],
    ['doc_special','doc_special_err','Special document is required.'],
    ['doc_entry_visa','doc_entry_err','Entry visa is required.'],
    ['doc_photo','doc_photo_err','Photo is required.'],
  ];
  docs.forEach(function(d) {
    var el = document.querySelector('[name="'+d[0]+'"]');
    if (!el || !el.files || el.files.length === 0) { showErr(d[1], d[2]); valid=false; } else hideErr(d[1]);
  });

  if (valid) document.querySelector('form').submit();
}
//

//
function medValidateDecl() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var decl = document.querySelector('[name="declaration_accepted"]');
  if (!decl || !decl.checked) { showErr('med_decl_err','Please agree to the declaration to proceed.'); valid=false; } else hideErr('med_decl_err');
  if (valid) document.querySelector('form').submit();
}
//

//
function mrValidateStep1() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var bd = document.querySelector('[name="booking_date"]');
  if (!bd || !bd.value) { showErr('bdate_err','Please select a booking date.'); valid=false; } else hideErr('bdate_err');
  var bt = document.querySelector('[name="booking_start_time"]');
  if (!bt || !bt.value) { showErr('btime_err','Please select a booking start time.'); valid=false; } else hideErr('btime_err');
  var dur = document.querySelector('[name="meeting_duration"]');
  if (!dur || !dur.value) { showErr('bdur_err','Please select a duration.'); valid=false; } else hideErr('bdur_err');
  if (valid) document.querySelector('form').submit();
}
//

//
var checked = {ind: false, com: false, inv: false};
function toggleCheck(key) {
    checked[key] = !checked[key];
    var box = document.getElementById(key+'-box');
    var val = document.getElementById(key+'-val');
    var sec = document.getElementById('sec-'+key);
    if(checked[key]) {
        box.style.background='#1a3c6e'; box.style.borderColor='#1a3c6e'; box.style.color='white';
        val.value = '1';
        if(sec) sec.style.display = 'flex';
    } else {
        box.style.background='white'; box.style.borderColor='#d1d5db'; box.style.color='transparent';
        val.value = '0';
        if(sec) sec.style.display = 'none';
    }
    updateSecNums();
}
function updateSecNums() {
    var n = 2;
    if(checked.ind) { document.querySelector('#sec-ind .sec-num').textContent = n++; }
    if(checked.com) { document.querySelector('#sec-com .sec-num').textContent = n++; }
    if(checked.inv) { document.querySelector('#sec-inv .sec-num').textContent = n++; }
    document.getElementById('country-sec-num').textContent = n;
}
function renderUploads(key, count) {
    var container = document.getElementById(key+'-uploads');
    container.innerHTML = '';
    var n = parseInt(count) || 0;
    for(var i=1; i<=n; i++) {
        var div = document.createElement('div');
        div.style.marginBottom = '12px';
        var label = document.createElement('div');
        label.className = 'upload-label';
        label.textContent = 'Upload document '+i;
        var uploadBox = document.createElement('label');
        uploadBox.className = 'upload-box';
        uploadBox.style.cursor = 'pointer';
        var icon = document.createElement('div');
        icon.className = 'upload-icon';
        icon.innerHTML = '&#8679;';
        var txt = document.createElement('div');
        txt.className = 'upload-text';
        txt.id = key+'-fn-'+i;
        txt.textContent = 'Upload document '+i;
        var inp = document.createElement('input');
        inp.type = 'file';
        inp.name = 'doc_'+key+'_'+i;
        inp.style.display = 'none';
        inp.setAttribute('data-upload-key', key+'-'+i);
        inp.onchange = (function(k, idx) {
            return function() {
                document.getElementById(k+'-fn-'+idx).textContent = this.files[0].name;
                hideErr(k+'-upload-'+idx+'-err');
            };
        })(key, i);
        var errDiv = document.createElement('div');
        errDiv.id = key+'-upload-'+i+'-err';
        errDiv.style.cssText = 'color:red;font-size:12px;display:none;margin-top:4px';
        errDiv.textContent = 'Document '+i+' is required.';
        uploadBox.appendChild(icon);
        uploadBox.appendChild(txt);
        uploadBox.appendChild(inp);
        div.appendChild(label);
        div.appendChild(uploadBox);
        div.appendChild(errDiv);
        container.appendChild(div);
    }
}
function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
function mofaValidateStep1() {
    var valid = true;
    // At least one doc type selected
    if (!checked.ind && !checked.com && !checked.inv) {
        showErr('doctype_err','Please select at least one document type.');
        valid = false;
    } else {
        hideErr('doctype_err');
    }
    // Origin country
    var oc = document.querySelector('[name="origin_country_id"]');
    if (!oc || !oc.value) { showErr('origin_err','Please select document origin country.'); valid=false; } else hideErr('origin_err');
    // Validate upload fields for each selected type
    var keys = [];
    if(checked.ind) keys.push(['ind', document.getElementById('ind-count')]);
    if(checked.com) keys.push(['com', document.getElementById('com-count')]);
    if(checked.inv) keys.push(['inv', document.getElementById('inv-count')]);
    keys.forEach(function(kc) {
        var key = kc[0], sel = kc[1];
        if (!sel || !sel.value) {
            showErr(key+'-count-err','Please select number of documents.');
            valid = false;
        } else {
            hideErr(key+'-count-err');
            var n = parseInt(sel.value);
            for(var i=1; i<=n; i++) {
                var inp = document.querySelector('[name="doc_'+key+'_'+i+'"]');
                if (!inp || !inp.files || inp.files.length === 0) {
                    showErr(key+'-upload-'+i+'-err','Document '+i+' is required.');
                    valid = false;
                } else {
                    hideErr(key+'-upload-'+i+'-err');
                }
            }
        }
    });
    if (valid) document.querySelector('form').submit();
}
//

//
function mofaValidateDecl() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var decl = document.querySelector('[name="declaration_accepted"]');
  if (!decl || !decl.checked) { showErr('mofa_decl_err','Please agree to the declaration to proceed.'); valid=false; } else hideErr('mofa_decl_err');
  if (valid) document.querySelector('form').submit();
}
//
